from __future__ import annotations

from dataclasses import dataclass, field
from typing import TYPE_CHECKING

from rasa.builder.copilot.pydantic_ai.types import RunRequest

if TYPE_CHECKING:
    from rasa.builder.copilot.pydantic_ai.plan import PlanState
    from rasa.builder.copilot.pydantic_ai.workspace import CopilotWorkspace
    from rasa.builder.copilot.skill_catalog import CopilotSkill
    from rasa.builder.shared.tracker_context import TrackerContext


def _new_plan_state() -> PlanState:
    """Build an empty plan. Imported lazily to avoid a plan ↔ run_context cycle."""
    from rasa.builder.copilot.pydantic_ai.plan import PlanState

    return PlanState()


@dataclass
class CopilotRunContext:
    """Per-run dependencies for a Copilot v2 run.

    ``project_path`` is resolved server-side (from the app's project generator)
    and is the single source of truth for both reads/writes and the end-of-run
    commit, so the client cannot redirect file operations to another directory.
    ``made_changes`` flips to ``True`` the moment a write tool succeeds; the
    end-of-run finalizer reads it to decide whether a commit is due.

    The completed turn is not accumulated here: persistence reads pydantic-ai's
    own ordered record of the run (``AgentRunResult.new_messages()``) at the end
    of the run, so history matches what the user saw without a parallel buffer.

    ``tracker_context`` is resolved server-side after ``RUN_STARTED`` and read
    only at prompt-build time.

    ``plan`` is the per-run checklist written by ``update_plan``. A new turn
    always starts empty — there is no cross-turn plan continuity.

    ``agent_id`` is sent with every MCP tool call's ``_meta`` so the MCP
    server, which serves every agent the builder hosts, resolves the same
    workspace as ``project_path``. ``uses_mantle_layout`` is probed once per
    run, off the event loop, because the MCP tool filter reading it runs on
    every model request.

    ``workspace`` is set only when the client opted into branching. It owns the
    branch the run is on; ``create_branch`` moves it to a new branch and
    repoints ``project_path`` at that branch's checkout.

    ``skills`` are the Copilot skills this run offers, picked by the skill
    policy of the project's engine at the start of the turn. The model loads
    them on demand; an empty tuple means the run offers no skills at all.
    """

    request: RunRequest
    project_path: str | None = None
    agent_id: str | None = None
    uses_mantle_layout: bool = False
    made_changes: bool = False
    tracker_context: TrackerContext | None = None
    plan: PlanState = field(default_factory=_new_plan_state)
    workspace: CopilotWorkspace | None = None
    skills: tuple[CopilotSkill, ...] = ()
